contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address account, address grantAdmin) public {
        vm.assume(grantAdmin != address(0) && grantAdmin != account);
        vm.assume(account != address(0));
        // Make grantAdmin the admin of the role
        vm.prank(address(this));
        c.grantRole(c.TIMELOCK_ADMIN_ROLE(), grantAdmin);
        // Grant the role to account via grantAdmin
        vm.prank(grantAdmin);
        c.grantRole(role, account);
        // The reference guarantees that after granting, hasRole(role, account) is true.
        // The buggy version returns false unconditionally, violating this.
        assertTrue(c.hasRole(role, account));
    }
}

