pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address account) public {
        // The DEFAULT_ADMIN_ROLE is bytes32(0). In the reference C, hasRole(0x00, account)
        // returns true because _grantRole is never called for it but the storage default is false;
        // however AccessControl grants no implicit roles.
        // Actually, let's examine: DEFAULT_ADMIN_ROLE = 0x00. _roles[0x00].members[account]
        // starts as false. The constructor does _setupRole(TIMELOCK_ADMIN_ROLE, _msgSender()) and
        // _setupRole(TIMELOCK_ADMIN_ROLE, address(this)), but nothing for 0x00.
        // So hasRole(0x00, any) is false in the reference. The bug also returns false.
        // That difference doesn't manifest.
        // Instead, use the fact that after granting any role to an account via _setupRole (which
        // calls _grantRole), hasRole for that role and account returns true. The bug returns false.
        // But those approaches were already tried.
        // New approach: The reference hasRole(role, account) returns true iff the role was granted
        // to the account. The bug always returns false. We can prove this by granting a role to
        // an address, then checking hasRole. But that already tried.
        // Let's find a rule that holds for all inputs without setup, purely from the constructor.
        // The constructor grants TIMELOCK_ADMIN_ROLE to the deployer (address(this) in setUp) and
        // to address(c). So c.hasRole(TIMELOCK_ADMIN_ROLE, any of those) is true. Bug returns false.
        // But we cannot hardcode the role (we can compute it from contract, as it's a public constant).
        // The fuzzer can't change the role; it's computed.
        // We can still fuzz the account parameter. For all accounts, hasRole(TIMELOCK_ADMIN_ROLE, account)
        // returns true iff account is one of the two granted in setUp. For any other account, it's false.
        // The bug returns false for all. So the property "hasRole(TIMELOCK_ADMIN_ROLE, account) == (account == address(c) || account == address(this))" holds in reference, but bug makes it false
        // when account is one of the two.
        // However, the assertion would need to know address(c) and address(this) which is okay.
        // Let's formulate: bool expected = (account == address(c) || account == address(this));
        // assertTrue(c.hasRole(c.TIMELOCK_ADMIN_ROLE(), account) == expected);
        // This requires the fuzz param 'account'. We must ensure the fuzzer can provide any address.
        // That works.
        vm.assume(account != address(0)); // optional, but widen domain
        bytes32 role = c.TIMELOCK_ADMIN_ROLE();
        bool has = c.hasRole(role, account);
        bool expected = (account == address(c) || account == address(this));
        assertTrue(has == expected);
    }
}

