pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address account) public {
        // 1. Setup: grant the fuzzed role to the fuzzed account
        // The contract itself has TIMELOCK_ADMIN_ROLE, so it can grant any role via grantRole's admin chain.
        // We give the contract the required admin role by granting role's admin to the contract.
        bytes32 adminRole = c.getRoleAdmin(role);
        // The contract itself has TIMELOCK_ADMIN_ROLE at construction. We need to ensure it has the direct admin of 'role'.
        // We can grant the admin role to the contract via the contract itself if it has that admin.
        if (!c.hasRole(adminRole, address(c))) {
            // Grant admin role to the contract if it doesn't have it
            vm.prank(address(c));
            c.grantRole(adminRole, address(c));
        }
        // Now the contract has the admin role, so it can grant 'role' to 'account'
        vm.prank(address(c));
        c.grantRole(role, account);

        // 2. Invariant: after granting, hasRole(role, account) must be true
        // The buggy version returns false unconditionally, breaking this.
        assertTrue(c.hasRole(role, account));
    }
}

