pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
        // Give TIMELOCK_ADMIN_ROLE to address(this) so we can set up roles
        vm.prank(address(this));
        c.grantRole(c.TIMELOCK_ADMIN_ROLE(), address(this));
        // Set up a role hierarchy: ROLE_A's admin is ROLE_B
        bytes32 ROLE_A = keccak256("ROLE_A");
        bytes32 ROLE_B = keccak256("ROLE_B");
        c.grantRole(ROLE_B, address(this));
        c.grantRole(c.TIMELOCK_ADMIN_ROLE(), address(this));
        c.grantRole(ROLE_A, address(this));
        vm.stopPrank();
    }
    function testFuzz_property(bytes32 role, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(!c.hasRole(c.getRoleAdmin(role), caller));
        vm.prank(caller);
        bool ok = true;
        try c.grantRole(role, caller) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: grantRole should revert if caller lacks the stored admin role.
        // The mutant getRoleAdmin returns bytes32(0), so the modifier onlyRole(getRoleAdmin(role))
        // would check DEFAULT_ADMIN_ROLE instead. Since DEFAULT_ADMIN_ROLE is 0x00 and no check
        // is performed for address(0) having it, the call reverts only if the caller does not have
        // DEFAULT_ADMIN_ROLE. The mutant thus lets a caller without the real admin role succeed.
        // Assert that the call reverted, which is true for the correct contract whenever caller
        // does not have the real admin role. The mutant will pass the modifier for some callers
        // that lack the real admin but have DEFAULT_ADMIN_ROLE, making ok = true.
        assertTrue(!ok);
    }
}

