pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address account) public {
        // 1. Admissible domain: role must not be zero, because zero is the default admin role and some roles may have zero admin; to observe the difference we need a role that has a non-zero admin set.
        // In the reference, TIMELOCK_ADMIN_ROLE and PROPOSER_ROLE have admin TIMELOCK_ADMIN_ROLE, EXECUTOR_ROLE has admin TIMELOCK_ADMIN_ROLE.
        // We prune role to be one of those to ensure getRoleAdmin(role) != 0 in reference.
        bytes32 timelockAdmin = keccak256("TIMELOCK_ADMIN_ROLE");
        bytes32 proposer = keccak256("PROPOSER_ROLE");
        bytes32 executor = keccak256("EXECUTOR_ROLE");
        vm.assume(role == timelockAdmin || role == proposer || role == executor);
        // account can be any address; we need to ensure account holds the admin role of `role` in the reference, so that hasRole succeeds in reference but fails in mutant.
        // We can grant the role's admin to account in setUp? No, setUp deploys c and grants admin roles only to address(this).
        // Instead, we can prank as address(this) (which holds TIMELOCK_ADMIN_ROLE, the admin of all these roles) and check whether hasRole(getRoleAdmin(role), account) is true.
        // But we need to control account; we cannot grant roles to arbitrary accounts without prank, but we can use address(this) as the account since it already holds the admin role.
        // So we set account = address(this) to avoid pranking grants.
        account = address(this);

        // 2. No adversarial helper needed; pure getter+hasRole check.

        // 3. Assert: The caller (address(this)) holds the admin role returned by getRoleAdmin(role), which is true in reference (returns timelockAdmin) but false in mutant (returns 0).
        bytes32 adminRole = c.getRoleAdmin(role);
        bool holdsAdmin = c.hasRole(adminRole, account);
        assertTrue(holdsAdmin);
    }
}

