import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, bytes32 adminRoleToSet) public {
        vm.assume(role != bytes32(0));
        vm.assume(adminRoleToSet != bytes32(0));
        vm.prank(address(c));
        c.updateDelay(0);
        c.grantRole(role, address(this));
        bytes32 previousAdmin = c.getRoleAdmin(role);
        bytes32 expectedAdmin = adminRoleToSet;
        vm.prank(address(c));
        c.grantRole(adminRoleToSet, address(this));
        vm.prank(address(c));
        c.setRoleAdmin(role, adminRoleToSet);
        bytes32 actualAdmin = c.getRoleAdmin(role);
        assertTrue(actualAdmin == expectedAdmin);
    }
}

