pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, bytes32 adminRoleToSet) public {
        // For any role and adminRoleToSet, after calling _setRoleAdmin via updateDelay trick
        // the getRoleAdmin should return adminRoleToSet
        vm.prank(address(c));
        c.updateDelay(uint256(uint160(address(this)))); // dummy call to satisfy onlyRole(0x00) self-check
        c.updateDelay(0);
        // Use the publicly accessible grantRole path to check getRoleAdmin, but we cannot call _setRoleAdmin directly.
        // Instead, we rely on the fact that DEFAULT_ADMIN_ROLE is 0x00 and TIMELOCK_ADMIN_ROLE has admin 0x00.
        // We can test by creating a new role and observing its admin via the only public getter.
        // Since _setRoleAdmin is internal, we must use another public function that calls it.
        // The only public function calling _setRoleAdmin is the constructor, so we redeploy c with different setup.
        // But we cannot redeploy; the rule must be tested on the existing c.
        // However, observe that roles initialized in constructor have known admins.
        // TIMELOCK_ADMIN_ROLE is its own admin (non-zero admin). PROPOSER_ROLE admin is TIMELOCK_ADMIN_ROLE (non-zero).
        // EXECUTOR_ROLE admin is TIMELOCK_ADMIN_ROLE (non-zero).
        // So we can test: getRoleAdmin of a role with non-zero admin must not be 0x00.
        // But the fuzzer provides role and adminRoleToSet — how to use them?
        // The only way to set a role admin after construction is through internal _setRoleAdmin, not accessible.
        // The difference property: getRoleAdmin(role) should return the admin set for that role.
        // We can test roles that already have non-zero admin (TIMELOCK_ADMIN_ROLE, PROPOSER_ROLE, EXECUTOR_ROLE).
        // Their getRoleAdmin must not be 0x00.
        // Use fuzzed role: choose from these constants or allow any bytes32.
        // For any role, if hasRole(role, some account) is true, it means role was set up.
        // But we can just assert that getRoleAdmin(TIMELOCK_ADMIN_ROLE) != 0x00.
        // That's a fixed witness, not general. But the fuzzer supplies role and adminRoleToSet.
        // The bug is: getRoleAdmin returns DEFAULT_ADMIN_ROLE always.
        // So for any role whose admin is not 0x00, getRoleAdmin(role) != DEFAULT_ADMIN_ROLE.
        // Since the reference sets TIMELOCK_ADMIN_ROLE as its own admin (non-zero), we can assert getRoleAdmin(TIMELOCK_ADMIN_ROLE) != 0x00.
        // But the test must take fuzzed parameters. We can use fuzzed role and assert: if role == TIMELOCK_ADMIN_ROLE, then getRoleAdmin(role) != 0x00.
        // That is too specific. A better general rule: for every role that was granted to address(this) (i.e., hasRole(role, address(this)) true),
        // getRoleAdmin(role) should not be DEFAULT_ADMIN_ROLE because the constructor sets non-zero admins for those roles.
        // But address(this) is the contract itself, which has TIMELOCK_ADMIN_ROLE.
        // We can use any role: if hasRole(role, address(this)) is true, then role was set up and its admin is known to be non-zero (or zero for 0x00).
        // However, the fuzzer might pick role = 0x00, which has admin 0x00 by default, so the rule would fail.
        // So we restrict: assume role != 0x00 and hasRole(role, address(this)).
        // Then getRoleAdmin(role) != 0x00.
        // The reference satisfies because all non-zero roles set in constructor have admin TIMELOCK_ADMIN_ROLE (non-zero).
        // The bug returns 0x00 for any role, so it fails for any role with hasRole true whose admin is not 0x00.
        vm.assume(role != bytes32(0));
        vm.assume(c.hasRole(role, address(this)));
        bytes32 admin = c.getRoleAdmin(role);
        assertTrue(admin != bytes32(0));
    }
}
